"use strict";

// Expand a compact "sampled polygon" (a polygon whose vertices are sampled over time, as
// generated by eclipsescraper's shadow.py) into CZML packets for Cesium.CzmlDataSource.
// Times are stored once as integer deltas (in 1/time_scale seconds after the epoch) and each
// vertex's longitudes and latitudes as integer deltas (in 1/coord_scale degrees). Mirrors
// expand_sampled_polygon() in eclipsescraper/src/eclipsescraper/shadow.py.
function expandSampledPolygon(compact) {
    if (compact.format !== "eclipsetracks.sampled_polygon" || compact.version !== 1) {
        throw new Error("Not a version 1 sampled polygon");
    }
    var n = compact.times.length;
    var times = new Array(n);
    var t = 0;
    for (var k = 0; k < n; k++) {
        t += compact.times[k];
        times[k] = t / compact.time_scale;
    }
    var scale = compact.coord_scale;
    var packets = [{ id: "document", version: "1.1", name: compact.name }];
    var references = [];
    for (var i = 0; i < compact.lon.length; i++) {
        var id = compact.vertex_id.replace("{i}", String(i).padStart(2, "0"));
        var lonDeltas = compact.lon[i];
        var latDeltas = compact.lat[i];
        var samples = new Array(4 * n);
        var lon = 0;
        var lat = 0;
        for (var k = 0; k < n; k++) {
            lon += lonDeltas[k];
            lat += latDeltas[k];
            samples[4 * k] = times[k];
            samples[4 * k + 1] = lon / scale;
            samples[4 * k + 2] = lat / scale;
            samples[4 * k + 3] = 0;
        }
        packets.push({
            id: id,
            availability: compact.availability,
            position: { epoch: compact.epoch, cartographicDegrees: samples, interpolationAlgorithm: "LINEAR" }
        });
        references.push(id + "#position");
    }
    packets.push({
        id: compact.id,
        availability: compact.availability,
        polygon: {
            show: true,
            material: { solidColor: { color: { rgba: compact.rgba } } },
            positions: { references: references }
        }
    });
    return packets;
}

// Allow use from Node (for validation scripts) as well as the browser bundle
if (typeof module !== "undefined" && module.exports) {
    module.exports = { expandSampledPolygon: expandSampledPolygon };
}
